exercises.prompt:
Given:
interface BadgeProps { value: number; max?: number }

Which of the following calls is valid?

Given:
interface MovieCardProps { title: string; rating: number; poster?: string }

Which JSX call will TypeScript accept?

exercises.code:
// Define the interface and component here

function WatchButton({ label, onWatch }) {
  return <button onClick={onWatch}>{label}</button>
}

exercises.answer:
interface WatchButtonProps {
  label: string
  onWatch?: () => void
}

function WatchButton({ label, onWatch }: WatchButtonProps) {
  return <button onClick={onWatch}>{label}</button>
}
